{"explanation":"The matrix sends each point (x, y) to (2x + y, y): it doubles the horizontal component and adds a horizontal shear, while leaving height unchanged. Its determinant is 2, so every region becomes twice as large in area; the positive sign means orientation is preserved. Drag either corner to compare a rectangle with its transformed parallelogram—the area ratio stays 2.","manimCode":"const ax = new Axes({ xRange: [-2, 6, 1], yRange: [-2.5, 2.5, 1], xLength: 9, yLength: 4, tips: false });
let width = 1.3;
let height = 1.4;
let showGrid = true;
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const imagePoint = (x, y) => ax.c2p(2 * x + y, y);

const title = new MathTex({ latex: 'A=\\begin{pmatrix}2&1\\\\0&1\\end{pmatrix}\\qquad (x,y)\\mapsto(2x+y,y)', color: WHITE });
await title.waitForRender();
title.scale(0.8);
title.moveTo([0, 3.1, 0]);
const subtitle = new Text({ text: 'Horizontal stretch + shear   |   det(A) = 2', fontSize: 23, color: WHITE });
subtitle.moveTo([0, 2.45, 0]);

const originalGrid = [];
for (let k = -2; k <= 6; k++) {
  const ln = new Line({ start: ax.c2p(k, -2.5), end: ax.c2p(k, 2.5), color: GRAY });
  ln.setOpacity(0.18);
  ln.setStrokeWidth(1);
  originalGrid.push(ln);
}
for (let k = -2; k <= 2; k++) {
  const ln = new Line({ start: ax.c2p(-2, k), end: ax.c2p(6, k), color: GRAY });
  ln.setOpacity(0.18);
  ln.setStrokeWidth(1);
  originalGrid.push(ln);
}
const mappedGrid = [];
// Images of vertical lines x = k become oblique lines X = 2k + Y.
// Clip every segment to the same visible coordinate window.
for (let k = -3; k <= 4; k++) {
  const lo = Math.max(-2.5, -2 - 2 * k);
  const hi = Math.min(2.5, 6 - 2 * k);
  if (hi > lo) {
    const ln = new Line({ start: imagePoint(k, lo), end: imagePoint(k, hi), color: TEAL });
    ln.setStrokeWidth(1.5);
    ln.setOpacity(0.38);
    mappedGrid.push(ln);
  }
}
scene.add(...originalGrid, ...mappedGrid, ax, title, subtitle);

const O = ax.c2p(0, 0);
const original = new Polygon({ vertices: [O, ax.c2p(width, 0), ax.c2p(width, height), ax.c2p(0, height)], color: BLUE });
original.setFill(BLUE, 0.25);
original.setStrokeWidth(3);
const mapped = new Polygon({ vertices: [O, imagePoint(width, 0), imagePoint(width, height), imagePoint(0, height)], color: YELLOW });
mapped.setFill(YELLOW, 0.2);
mapped.setStrokeWidth(3);
const blueHandle = new Dot({ point: ax.c2p(width, height), radius: 0.13, color: BLUE });
const yellowHandle = new Dot({ point: imagePoint(width, height), radius: 0.13, color: YELLOW });
const correspondence = new DashedLine({ start: blueHandle.getCenter(), end: yellowHandle.getCenter(), color: WHITE });
correspondence.setOpacity(0.45);

const originalReadout = new Text({ text: '', fontSize: 24, color: BLUE });
originalReadout.moveTo([-2.6, -2.45, 0]);
const mappedReadout = new Text({ text: '', fontSize: 24, color: YELLOW });
mappedReadout.moveTo([2.6, -2.45, 0]);
const ratio = new Text({ text: 'Image area / original area = 2', fontSize: 25, color: WHITE });
ratio.moveTo([0, -2.95, 0]);
const hint = new Text({ text: 'Drag either bright corner to resize the rectangle', fontSize: 21, color: GRAY });
hint.moveTo([0, -3.45, 0]);
const gridToggle = new Text({ text: '', fontSize: 18, color: TEAL });
gridToggle.moveTo([4.8, 1.85, 0]);
const dimensionReadout = new Text({ text: '', fontSize: 19, color: WHITE });
dimensionReadout.moveTo([-2.5, 1.8, 0]);

function update() {
  original.setVertices([O, ax.c2p(width, 0), ax.c2p(width, height), ax.c2p(0, height)]);
  mapped.setVertices([O, imagePoint(width, 0), imagePoint(width, height), imagePoint(0, height)]);
  blueHandle.moveTo(ax.c2p(width, height));
  yellowHandle.moveTo(imagePoint(width, height));
  correspondence.setStart(ax.c2p(width, height));
  correspondence.setEnd(imagePoint(width, height));
  const area = width * height;
  originalReadout.setText('Original area = ' + area.toFixed(2));
  mappedReadout.setText('Image area = ' + (2 * area).toFixed(2));
  dimensionReadout.setText('w = ' + width.toFixed(2) + '    h = ' + height.toFixed(2));
  gridToggle.setText(showGrid ? 'Hide image grid' : 'Show image grid');
  mappedGrid.forEach(ln => ln.setOpacity(showGrid ? 0.38 : 0));
}
update();
await scene.play(new AnimationGroup([new DrawBorderThenFill(original), new DrawBorderThenFill(mapped)]));
scene.add(correspondence, blueHandle, yellowHandle, originalReadout, mappedReadout, ratio, hint, gridToggle, dimensionReadout);

makeDraggable(blueHandle, scene, { onDrag: (mob, pos) => {
  const p = ax.pointToCoords(pos);
  width = clamp(p[0], 0.5, 1.65);
  height = clamp(p[1], 0.5, 1.8);
  update();
} });
makeDraggable(yellowHandle, scene, { onDrag: (mob, pos) => {
  const p = ax.pointToCoords(pos);
  // Pull the dragged image point back through A inverse.
  width = clamp((p[0] - p[1]) / 2, 0.5, 1.65);
  height = clamp(p[1], 0.5, 1.8);
  update();
} });
makeClickable(gridToggle, scene, { onClick: () => {
  showGrid = !showGrid;
  update();
} });

const hoverInfo = new Text({ text: '', fontSize: 20, color: WHITE });
hoverInfo.moveTo([0, -2.05, 0]);
makeHoverable(yellowHandle, scene, {
  onHoverStart: () => {
    hoverInfo.setText('Corner image: (' + (2 * width + height).toFixed(2) + ', ' + height.toFixed(2) + ')');
    scene.add(hoverInfo);
  },
  onHoverEnd: () => scene.remove(hoverInfo)
});
await scene.wait(999999);"}

